import { getApiBaseUrlEnv } from "../../../config/env.js";
import { CACHE_ERROR, NETWORK_ERROR } from "../../../errors/index.js";
import { injectContext } from "../../../observability/tracing/otlp-setup.js";
import { transformToESM } from "../../../transforms/esm/index.js";
import { HTTP_FETCH_TIMEOUT_MS } from "../../../utils/constants/http.js";
import { writeCacheFile } from "../../../utils/cache-file-ops.js";
import { rendererLogger as logger } from "../../../utils/index.js";
import { globalCrossProjectCache } from "./cache/index.js";
import { readLimitedCrossProjectSource } from "../../server/cross-project-source-limit.js";
import { buildDependencyPinningCacheVariant } from "../../../cache/keys/dependency-pinning.js";
import { encodeCacheKeySegment } from "../../../cache/keys/segment-codec.js";
import { base64urlEncode } from "../../../utils/base64url.js";
function getRegistryBaseUrl(apiBaseUrl) {
    const resolvedApiBaseUrl = apiBaseUrl || getApiBaseUrlEnv();
    return resolvedApiBaseUrl.replace(/\/api\/?$/, "");
}
export function buildCrossProjectImportCacheKey(options) {
    const reactVersion = options.reactVersion ?? "default";
    const projectKey = encodeCacheKeySegment(options.projectId);
    const registryKey = base64urlEncode(options.registryBaseUrl);
    const baseKey = `${options.specifier}:${reactVersion}:owner:${projectKey}:registry:${registryKey}`;
    const cacheVariant = buildDependencyPinningCacheVariant(options.dependencyPinningCacheKey, options.moduleServerOrigin);
    return cacheVariant ? `${baseKey}:${cacheVariant}` : baseKey;
}
export async function transformCrossProjectImportFlow(flowOptions) {
    const { crossProjectImport, options, cache, withTransformCapacity, fetchImpl = fetch, transformToESMImpl = transformToESM, injectContextImpl = injectContext, loggerImpl = logger, fetchTimeoutMs = HTTP_FETCH_TIMEOUT_MS, } = flowOptions;
    const { specifier, projectSlug, version, path } = crossProjectImport;
    const registryBaseUrl = getRegistryBaseUrl(options.apiBaseUrl);
    const cacheKey = buildCrossProjectImportCacheKey({
        specifier,
        projectId: options.projectId,
        reactVersion: options.reactVersion,
        registryBaseUrl,
        moduleServerOrigin: options.moduleServerOrigin,
        dependencyPinningCacheKey: options.dependencyPinningCacheKey,
    });
    const cachedEntry = globalCrossProjectCache.get(cacheKey);
    if (cachedEntry)
        return cachedEntry.tempPath;
    const projectRef = `${projectSlug}@${version}`;
    const registryUrl = `${registryBaseUrl}/${projectRef}/@/${path}`;
    loggerImpl.debug("[SSR-MODULE-LOADER] Fetching cross-project import", {
        specifier,
        registryUrl,
    });
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), fetchTimeoutMs);
    try {
        const headers = new Headers({
            Accept: "text/plain, application/javascript, */*",
        });
        injectContextImpl(headers);
        const response = await fetchImpl(registryUrl, { signal: controller.signal, headers });
        clearTimeout(timeout);
        if (!response.ok) {
            throw NETWORK_ERROR.create({
                detail: `Failed to fetch ${registryUrl}: ${response.status} ${response.statusText}`,
            });
        }
        const sourceCode = await readLimitedCrossProjectSource(response, registryUrl);
        const contentHash = await cache.hashContentAsync(sourceCode);
        const ext = path.match(/\.(tsx?|jsx?|mdx)$/)?.[0] ?? ".tsx";
        const syntheticFilePath = `cross-project/${projectRef}/@/${path}`;
        const tempPath = await cache.getTempPath(syntheticFilePath, contentHash);
        return await withTransformCapacity(syntheticFilePath, async () => {
            const projectId = options.projectId;
            const transformOpts = {
                projectId,
                dev: options.dev,
                ssr: true,
                apiBaseUrl: options.apiBaseUrl,
                moduleServerOrigin: options.moduleServerOrigin,
                reactVersion: options.reactVersion,
                dependencyPinningCacheKey: options.dependencyPinningCacheKey,
                dependencyPinningDependencies: options.dependencyPinningDependencies,
                dependencyPinningConfiguredVersions: options.dependencyPinningConfiguredVersions,
                dependencyPinningSource: options.dependencyPinningSource,
            };
            const filePathWithExt = syntheticFilePath.endsWith(ext)
                ? syntheticFilePath
                : syntheticFilePath + ext;
            const transformed = await transformToESMImpl(sourceCode, filePathWithExt, options.projectDir, options.adapter, transformOpts);
            const written = await writeCacheFile(cache.getFs(), tempPath, transformed, "SSR-MODULE-LOADER");
            if (!written) {
                throw CACHE_ERROR.create({
                    detail: `Failed to write cross-project import cache file: ${tempPath}`,
                });
            }
            globalCrossProjectCache.set(cacheKey, { tempPath, contentHash });
            loggerImpl.debug("[SSR-MODULE-LOADER] Cross-project import transformed", {
                specifier,
                tempPath,
            });
            return tempPath;
        });
    }
    catch (error) {
        clearTimeout(timeout);
        loggerImpl.error("[SSR-MODULE-LOADER] Failed to fetch cross-project import", {
            specifier,
            registryUrl,
            error: error instanceof Error ? error.message : String(error),
        });
        throw error;
    }
}
